#include <cstdio>
#include <vector>

long long mergeCount(std::vector<long long>& a, std::vector<long long>& tmp, int l, int r) {
    if (l >= r) return 0;
    int mid = l + (r - l) / 2;
    long long cnt = mergeCount(a, tmp, l, mid) + mergeCount(a, tmp, mid + 1, r);

    int i = l, j = mid + 1, k = l;
    while (i <= mid && j <= r) {
        if (a[i] <= a[j]) tmp[k++] = a[i++];
        else {
            tmp[k++] = a[j++];
            cnt += mid - i + 1;   // 左半剩余元素都与 a[j] 构成逆序对
        }
    }
    while (i <= mid) tmp[k++] = a[i++];
    while (j <= r) tmp[k++] = a[j++];
    for (int t = l; t <= r; ++t) a[t] = tmp[t];
    return cnt;
}

int main() {
    int n;
    scanf("%d", &n);
    std::vector<long long> a(n);
    for (int i = 0; i < n; ++i) scanf("%lld", &a[i]);

    std::vector<long long> tmp(n);
    printf("%lld\n", mergeCount(a, tmp, 0, n - 1));
    return 0;
}
